package declarative

import (
	"fmt"
	"regexp"
	"slices"
	"strconv"
	"strings"

	"github.com/birdtable/gragas-plugin-sdk/declarative/internal/canon"
	"github.com/birdtable/gragas-plugin-sdk/declarative/internal/model"
	"github.com/birdtable/gragas-plugin-sdk/declarative/internal/ordered"
)

// PresetFile is one generated file of one tool.
type PresetFile struct {
	// File is the path, relative to the config set, and the bytes.
	File model.File
	// Tool is the tool the file configures.
	Tool string
	// CopyOnce is set where the tool has no extends: a project copies the file
	// once and owns it, so the mark says the engine does not write it again.
	CopyOnce bool
}

// Shipped is one binding the presets ship, with where it went. It is how every
// entry of a preset traces to the one binding that set it.
type Shipped struct {
	// Rule is the rule that holds the binding.
	Rule model.RuleID
	// Binding is the binding as the rule holds it.
	Binding model.Binding
	// File is the preset file the entry is in: the main file, or for a tool
	// that keeps one file per entry, that entry's file.
	File string
	// Written is the severity word written for the entry, "" where none is.
	Written string
}

// Wire is how a project comes to use one tool's preset, from the adapter's
// wiring data. The engine never runs an install.
type Wire struct {
	Tool    string
	Import  *model.ImportAt
	Install []string
}

// Generated is the presets of one resolved rulebook. A layer of a chain
// is the caller's loop over the books it resolves.
type Generated struct {
	// Files are the preset files, in the order of their paths.
	Files []PresetFile
	// Shipped are the bindings written, in the order of tool, key and rule.
	Shipped []Shipped
	// Wiring is one row per tool that has any, in the order of the tools.
	Wiring []Wire
	// Mark, when it is set, is the text of the mark in the first line of each file, in place of the generated mark
	// (a plugin's request names it).
	Mark string
	// Notes name, in the engine's words, each binding not shipped and each
	// entry written other than as the rulebook states it. They hold no date.
	Notes []string
}

const (
	markGenerated = "Generated by gragas from the rulebook. Regenerate it, never change it by hand."
	markCopyOnce  = "Written once by gragas from the rulebook. It is yours to edit: gragas does not write it again."
	noWarning     = "trial: this tool has no warning level, so it fails as an error here"
)

var safeFile = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)

// candidate is a binding on its way to a preset.
type candidate struct {
	rule  model.RuleID
	trial bool
	b     model.Binding
}

// Generate writes the preset files of the book, one per tool, each whole and
// with the generated mark in the tool's own comment syntax. A binding of an
// active or trial rule at rung 0 to 5 ships, proven or not; a binding in an
// open entry conflict of the chain is blocked and is named in Notes, not
// shipped. A trial binding ships at its tool's warning level; a tool with
// none ships it at its only severity, and Notes carry the consumer action.
// Where a tool keeps severity in a table of overrides, the entry is
// listed in the table under its level when it is not the tool's error level,
// at the places placement.severity_table and severity_item name; an adapter
// that names none gets a note, and no table. The fixed lines of
// the preset (preset.lines, such as a version) open the main file.
//
// An adapter that names a settings input (preset.settings) is written from
// that input, whose text is settings[tool]: the generated mark, then the text
// with the list of linters spliced between its two marker lines (see
// generateSettings). Generate answers an error where such an adapter has no
// entry in settings, where its input has no markers, one of them twice, or
// content between them, and where no active or trial rule binds a linter of
// the tool. An adapter that names none is written as ever, and settings may
// be nil.
//
// The result is a function of the book's rules, the table, the chain and the
// settings, and of the order of none of them. It reads no file and no clock. Where several
// versions of an adapter exist, the one with the highest tool_versions text
// by canon order is read, since every version of a tool holds one preset.
func Generate(book model.Book, table Table, chain model.Chain, settings map[string][]byte) (Generated, error) {
	var out Generated
	adapters := newestAdapters(table)
	byTool := collect(&out, book, adapters, chain)
	for _, tool := range canon.SortedKeys(adapters) {
		cs, bound := byTool[tool]
		switch ad := adapters[tool]; {
		case !bound:
		case ad.Preset.Settings == nil:
			generateTool(&out, ad, cs)
		default:
			text, ok := settings[tool]
			if !ok {
				return Generated{}, fmt.Errorf("%s: %w", tool, ErrNoSettings)
			}
			if err := generateSettings(&out, ad, cs, text); err != nil {
				return Generated{}, err
			}
		}
	}
	slices.SortFunc(out.Files, func(a, b PresetFile) int { return canon.Compare(a.File.Path, b.File.Path) })
	slices.SortFunc(out.Shipped, func(a, b Shipped) int {
		return cmpAll(canon.Compare(a.Binding.Tool, b.Binding.Tool), canon.Compare(a.Binding.Key, b.Binding.Key),
			canon.Compare(string(a.Rule), string(b.Rule)), canon.Compare(string(a.Binding.Target), string(b.Binding.Target)))
	})
	slices.Sort(out.Notes)
	return out, nil
}

// collect is the bindings of the active and trial rules that ship, by tool; a
// binding that does not ship adds its note to out.
func collect(out *Generated, book model.Book, adapters map[string]model.Adapter, chain model.Chain) map[string][]candidate {
	byTool := map[string][]candidate{}
	for _, r := range book.Rules {
		if r.Status != model.Active && r.Status != model.Trial {
			continue
		}
		for _, b := range r.Bindings {
			if b.Rung >= model.MaxRung {
				continue
			}
			where := fmt.Sprintf("%s: %s %s %s", r.ID, b.Tool, b.Target, b.Key)
			ad, ok := adapters[b.Tool]
			switch {
			case chain.Blocks(b.Ref(r.ID)):
				out.Notes = append(out.Notes, where+" is not shipped: it is in an open entry conflict")
			case !ok:
				out.Notes = append(out.Notes, where+" is not shipped: no adapter holds the tool")
			case !slices.Contains(ad.Targets, b.Target):
				out.Notes = append(out.Notes, where+" is not shipped: the tool does not cover that target")
			default:
				byTool[b.Tool] = append(byTool[b.Tool], candidate{r.ID, r.Status == model.Trial, b})
			}
		}
	}
	return byTool
}

// newestAdapters is the adapter Generate reads for each tool: the one with the
// highest tool_versions text by canon order.
func newestAdapters(table Table) map[string]model.Adapter {
	adapters := map[string]model.Adapter{}
	for _, a := range table.All() {
		if old, ok := adapters[a.Tool]; !ok || canon.Compare(a.ToolVersions, old.ToolVersions) > 0 {
			adapters[a.Tool] = a
		}
	}
	return adapters
}

// SettingsInputs is, by tool, the settings input the adapter Generate reads
// for the tool names, for each tool whose adapter names one and which an
// active or trial rule of the book binds at a rung that ships: the tools
// Generate writes a file for. It is how a caller knows which files to read
// into Generate's settings argument, and a book that binds no such tool has
// none.
func SettingsInputs(book model.Book, table Table) map[string]model.PresetSettings {
	out := map[string]model.PresetSettings{}
	ads := newestAdapters(table)
	for _, r := range book.Rules {
		if r.Status != model.Active && r.Status != model.Trial {
			continue
		}
		for _, b := range r.Bindings {
			if a, ok := ads[b.Tool]; ok && b.Rung < model.MaxRung && a.Preset.Settings != nil {
				out[b.Tool] = *a.Preset.Settings
			}
		}
	}
	return out
}

func cmpAll(cs ...int) int {
	for _, c := range cs {
		if c != 0 {
			return c
		}
	}
	return 0
}

// toolDoc is the preset of one tool as it is built.
type toolDoc struct {
	out      *Generated
	ad       model.Adapter
	doc      any
	files    map[string]any
	seen     map[string]candidate
	folded   map[string]candidate
	noted    bool
	table    map[string][]string
	copyOnce bool
}

// generateTool adds one tool's file or files to out.
func generateTool(out *Generated, ad model.Adapter, cs []candidate) {
	slices.SortFunc(cs, func(a, b candidate) int {
		return cmpAll(canon.Compare(a.b.Key, b.b.Key), canon.Compare(string(a.rule), string(b.rule)),
			canon.Compare(string(a.b.Target), string(b.b.Target)))
	})
	d := &toolDoc{out: out, ad: ad, files: map[string]any{}, seen: map[string]candidate{}, folded: map[string]candidate{}, table: map[string][]string{}, copyOnce: !ad.Extends}
	head := ordered.NewMap(0)
	for _, l := range ad.Preset.Lines {
		if l.Items != nil {
			head.Set(l.Key, toOrdered(l.Items), 0)
		} else {
			head.Set(l.Key, l.Value, 0)
		}
	}
	d.doc = head
	for _, c := range cs {
		d.add(c)
	}
	d.writeTable()
	p := ad.Preset
	main := d.doc
	if m := asMap(d.doc); m.Len() == 0 && p.Placement.Shape == model.ShapeFiles {
		main = nil
	}
	out.Files = append(out.Files, PresetFile{File: model.File{Path: p.Path, Data: render(p, main, d.copyOnce, out.Mark)}, Tool: ad.Tool, CopyOnce: d.copyOnce})
	for _, f := range canon.SortedKeys(d.files) {
		out.Files = append(out.Files, PresetFile{File: model.File{Path: f, Data: render(p, d.files[f], d.copyOnce, out.Mark)}, Tool: ad.Tool, CopyOnce: d.copyOnce})
	}
	if w := p.Wiring; w != nil {
		out.Wiring = append(out.Wiring, Wire{Tool: ad.Tool, Import: w.Import, Install: slices.Clone(w.Install)})
	}
}

// sameEntry says whether two bindings of an entry state it alike.
func sameEntry(a, b model.Binding) bool {
	return fmt.Sprintf("%#v %#v %q", a.Value, a.Options, a.Severity) == fmt.Sprintf("%#v %#v %q", b.Value, b.Options, b.Severity)
}

// partOtherwise names the first part, of value, options and severity, that
// two bindings of an entry state otherwise; sameEntry has found one.
func partOtherwise(a, b model.Binding) string {
	switch {
	case fmt.Sprintf("%#v", a.Value) != fmt.Sprintf("%#v", b.Value):
		return "value"
	case fmt.Sprintf("%#v", a.Options) != fmt.Sprintf("%#v", b.Options):
		return "options"
	}
	return "severity"
}

// add writes one candidate's entry, or names why it is not written.
func (d *toolDoc) add(c candidate) {
	pl := d.ad.Preset.Placement
	where := fmt.Sprintf("%s: %s %s %s", c.rule, c.b.Tool, c.b.Target, c.b.Key)
	first, dup := d.seen[c.b.Key]
	if dup && !sameEntry(first.b, c.b) {
		d.out.Notes = append(d.out.Notes, fmt.Sprintf("%s is not written: %s already sets the entry's %s otherwise", where, first.rule, partOtherwise(first.b, c.b)))
		return
	}
	word, note := severityWord(d.ad.Severities, c)
	if note != "" {
		d.out.Notes = append(d.out.Notes, where+": "+note)
	}
	if d.ad.Severities.Form == model.SeverityTable {
		word = d.tabled(c, word)
	}
	file := d.ad.Preset.Path
	switch {
	case d.ad.Preset.Format == model.PresetJS && (c.b.Key == protoKey || hasProtoKey(toOrdered(c.b.Value)) || hasProtoKey(toOrdered(c.b.Options))):
		d.out.Notes = append(d.out.Notes, where+" is not written: a JS object literal reads the key "+protoKey+" as the prototype, not as a property")
		return
	case pl.Shape == model.ShapeFiles && !safeFile.MatchString(c.b.Key):
		d.out.Notes = append(d.out.Notes, where+" is not written: the key is no file name")
		return
	case pl.Shape == model.ShapeFiles:
		file = pl.Dir + "/" + c.b.Key + extension(file)
		// Two keys that differ only in case are one file where the file
		// system folds case, and the later write would replace the first
		// entry's whole file: the first stays written.
		if other, ok := d.folded[strings.ToLower(c.b.Key)]; ok && other.b.Key != c.b.Key {
			d.out.Notes = append(d.out.Notes, fmt.Sprintf("%s is not written: its key %s and %s's key %s are one file, %s, on a file system that folds case", where, c.b.Key, other.rule, other.b.Key, file))
			return
		}
		if option, place := topClash(pl, c.b); option != "" {
			d.out.Notes = append(d.out.Notes, fmt.Sprintf("%s is not written: its option %q is where placement.%s writes", where, option, place))
			return
		}
		d.files[file] = entryDoc(pl, c.b, word)
		d.folded[strings.ToLower(c.b.Key)] = c
	case !dup:
		d.doc = place(d.doc, pl, c.b, word)
	}
	d.seen[c.b.Key] = c
	d.out.Shipped = append(d.out.Shipped, Shipped{Rule: c.rule, Binding: c.b, File: file, Written: word})
}

// protoKey is the one key a JS object literal does not make a property of.
const protoKey = "__proto__"

// hasProtoKey says whether v, in the forms the writers take, holds a map key
// protoKey at any depth.
func hasProtoKey(v any) bool {
	switch x := v.(type) {
	case *ordered.Map:
		for _, k := range x.Keys() {
			e, _ := x.Get(k)
			if k == protoKey || hasProtoKey(e) {
				return true
			}
		}
	case []any:
		return slices.ContainsFunc(x, hasProtoKey)
	}
	return false
}

// tabled files the entry in the severity table under word, where the tool's
// error level is the default that needs no item, and returns the word the
// entry is written with: none, for the table holds it. An adapter that names
// no table or item shape gets one note and no table.
func (d *toolDoc) tabled(c candidate, word string) string {
	pl := d.ad.Preset.Placement
	if word == "" {
		return ""
	}
	if pl.SeverityTable == "" || pl.SeverityItem.Shape == "" {
		if !d.noted {
			d.noted = true
			d.out.Notes = append(d.out.Notes, c.b.Tool+": no severity table is written: the adapter gives no shape for its items")
		}
		return ""
	}
	if !d.isError(word) {
		d.table[word] = append(d.table[word], c.b.Key)
	}
	return word
}

// isError says whether word is the tool's level for an error.
func (d *toolDoc) isError(word string) bool {
	for _, l := range d.ad.Severities.Levels {
		if l.Name == word {
			return l.Is == model.SeverityError
		}
	}
	return false
}

// writeTable puts the severity table into the main document: one item a level,
// in the order the adapter lists its levels, naming the entries at that level.
func (d *toolDoc) writeTable() {
	pl := d.ad.Preset.Placement
	if len(d.table) == 0 {
		return
	}
	var items any
	switch pl.SeverityItem.Shape {
	case model.ShapeList:
		items = d.tableList(pl.SeverityItem)
	case model.ShapeObject:
		m := ordered.NewMap(0)
		for _, lv := range d.ad.Severities.Levels {
			for _, k := range d.table[lv.Name] {
				m.Set(k, put(nil, segments(pl.SeverityItem.Level), func(any) any { return lv.Name }), 0)
			}
		}
		items = m
	default:
		return
	}
	d.doc = put(d.doc, segments(pl.SeverityTable), func(any) any { return items })
}

// tableList is the items of a table that is a list: an item names its key or
// keys and its level at the places the item shape gives.
func (d *toolDoc) tableList(it model.SeverityItem) []any {
	l := []any{}
	one := func(key any, level string) any {
		return put(put(nil, segments(it.Key), func(any) any { return key }), segments(it.Level), func(any) any { return level })
	}
	for _, lv := range d.ad.Severities.Levels {
		keys := d.table[lv.Name]
		switch {
		case len(keys) == 0:
		case it.KeyForm == model.KeyList:
			l = append(l, one(toOrdered(keys), lv.Name))
		default:
			for _, k := range keys {
				l = append(l, one(k, lv.Name))
			}
		}
	}
	return l
}

// severityWord is the tool's word for the binding's entry, and a note where the
// word is not what the rulebook states.
func severityWord(s model.SeverityScale, c candidate) (word, note string) {
	if c.trial && s.Warning != "" {
		return s.Warning, ""
	}
	for _, l := range s.Levels {
		if l.Is == c.b.Severity {
			if c.trial {
				return l.Name, noWarning
			}
			return l.Name, ""
		}
	}
	if c.b.Severity == "" || len(s.Levels) == 0 {
		return "", ""
	}
	return "", fmt.Sprintf("severity %s is none of the tool's levels, so none is written", c.b.Severity)
}

func extension(path string) string {
	if i := strings.LastIndexByte(path, '.'); i >= 0 {
		return path[i:]
	}
	return ""
}

// place writes one entry into the document of a list or object preset.
func place(doc any, pl model.Placement, b model.Binding, word string) any {
	each := segments(pl.Each)
	switch pl.Shape {
	case model.ShapeList:
		doc = put(doc, each, func(old any) any {
			return append(asList(old), b.Key)
		})
		if pl.OptionsAt == "" || len(b.Options) == 0 {
			return doc
		}
		// A list's entry is its bare name, so the options go where options_at names, at the binding's key.
		// The key is set as a name, as the object shape sets its own: put would read a key of
		// digits as a list index, and a rule's key is any text. The steps before {key} and after it go through put.
		steps := segments(pl.OptionsAt)
		at := slices.Index(steps, "{key}")
		return put(doc, steps[:at], func(old any) any {
			m := asMap(old)
			held, _ := m.Get(b.Key)
			m.Set(b.Key, put(held, steps[at+1:], func(any) any { return toOrdered(b.Options) }), 0)
			return m
		})
	default:
		ev := entryDoc(pl, b, word)
		return put(doc, each, func(old any) any {
			m := asMap(old)
			m.Set(b.Key, ev, 0)
			return m
		})
	}
}

// entryDoc is what one entry holds: its value, options and severity at the
// places the placement names, or the value alone where it names none.
func entryDoc(pl model.Placement, b model.Binding, word string) any {
	if pl.Value == "" && pl.Options == "" && !pl.OptionsTop && pl.Severity == "" && pl.Key == "" {
		return toOrdered(b.Value)
	}
	var ev any
	set := func(ptr string, v any) {
		if ptr != "" {
			ev = put(ev, segments(ptr), func(any) any { return v })
		}
	}
	set(pl.Key, b.Key)
	if b.Value != nil {
		set(pl.Value, toOrdered(b.Value))
	}
	if len(b.Options) > 0 && pl.OptionsTop {
		// Each option is a member at the top, set by name and not through
		// put, which would read a name of digits as a list index; topClash
		// has refused a name the placement's own pointers write.
		top := asMap(ev)
		for _, k := range canon.SortedKeys(b.Options) {
			top.Set(k, toOrdered(b.Options[k]), 0)
		}
		ev = top
	} else if len(b.Options) > 0 {
		set(pl.Options, toOrdered(b.Options))
	}
	if word != "" {
		set(pl.Severity, word)
	}
	return ev
}

// topClash is, for a placement that writes options at the top of the entry's
// file, the first of the binding's options, in canon order, whose name is the
// first step of the key, value or severity pointer, and the name of that
// pointer; "" where none is. Such an option would be written over the entry's
// own part, or under it.
func topClash(pl model.Placement, b model.Binding) (option, place string) {
	if !pl.OptionsTop {
		return "", ""
	}
	for _, k := range canon.SortedKeys(b.Options) {
		for _, p := range []struct{ name, ptr string }{{"key", pl.Key}, {"value", pl.Value}, {"severity", pl.Severity}} {
			if steps := segments(p.ptr); len(steps) > 0 && steps[0] == k {
				return k, p.name
			}
		}
	}
	return "", ""
}

// segments splits a JSON pointer into its unescaped segments.
func segments(ptr string) []string {
	if ptr == "" {
		return nil
	}
	parts := strings.Split(ptr[1:], "/")
	for i, s := range parts {
		parts[i] = strings.ReplaceAll(strings.ReplaceAll(s, "~1", "/"), "~0", "~")
	}
	return parts
}

func isIndex(s string) bool {
	if s == "" || len(s) > 6 {
		return false
	}
	for _, r := range s {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// put returns parent with f applied to what is at segs, making a list of a
// numeric segment and an object of any other.
func put(parent any, segs []string, f func(old any) any) any {
	if len(segs) == 0 {
		return f(parent)
	}
	if isIndex(segs[0]) {
		l := asList(parent)
		n, err := strconv.Atoi(segs[0])
		if err != nil {
			return parent // isIndex held, so not reached
		}
		for len(l) <= n {
			l = append(l, nil)
		}
		l[n] = put(l[n], segs[1:], f)
		return l
	}
	m := asMap(parent)
	old, _ := m.Get(segs[0])
	m.Set(segs[0], put(old, segs[1:], f), 0)
	return m
}

// toOrdered is v in the forms the writers take, a map's keys in canon order.
func toOrdered(v any) any {
	switch x := v.(type) {
	case map[string]any:
		m := ordered.NewMap(0)
		for _, k := range canon.SortedKeys(x) {
			m.Set(k, toOrdered(x[k]), 0)
		}
		return m
	case []any:
		l := make([]any, len(x))
		for i, e := range x {
			l[i] = toOrdered(e)
		}
		return l
	case []string:
		l := make([]any, len(x))
		for i, e := range x {
			l[i] = e
		}
		return l
	default:
		return v
	}
}

// render is a preset file: the mark in the tool's comment syntax, then the
// document in the tool's format. A nil document is the mark alone.
func render(p model.Preset, doc any, copyOnce bool, asked string) []byte {
	mark := markGenerated
	if copyOnce {
		mark = markCopyOnce
	}
	if asked != "" {
		mark = asked
	}
	head := markLine(p.Comment, mark)
	if doc == nil {
		return []byte(head)
	}
	switch p.Format {
	case model.PresetYAML:
		return []byte(head + ordered.YAML(doc))
	case model.PresetJS:
		return []byte(head + "export default " + ordered.JSON(doc, 2) + ";\n")
	default:
		return []byte(head + ordered.JSON(doc, 2) + "\n")
	}
}

// asList is v as a list, or none where it is not one.
func asList(v any) []any {
	if l, ok := v.([]any); ok {
		return l
	}
	return nil
}

// asMap is v as an object, or an empty one where it is not one.
func asMap(v any) *ordered.Map {
	if m, ok := v.(*ordered.Map); ok && m != nil {
		return m
	}
	return ordered.NewMap(0)
}
